def build_tree(edges):
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)
    return tree

def dfs(tree, start, end, visited, path):
    if start == end:
        return True
    visited[start] = True
    for neighbor in tree[start]:
        if not visited[neighbor]:
            if dfs(tree, neighbor, end, visited, path):
                path.append(neighbor)
                return True
    return False

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

